use vstd::prelude::*;

verus! {

spec fn replaced_seq(s: Seq<i32>, x: i32, y: i32) -> Seq<i32> {
    s.map(|i: int, e: i32| if e == x { y } else { e })
}

fn replace(v: &mut Vec<i32>, x: i32, y: i32)
    ensures
        v@ == replaced_seq(old(v@), x, y),
{
    let ghost old_v: Seq<i32> = v@;

    for elem in v.iter_mut()
        invariant
            v@.len() == old_v.len(),
            // Elements before the current iterator position have been replaced;
            // the rest are unchanged from the old vector.
            exists|k: int|
                0 <= k <= v@.len()
                && v@.subrange(0, k) == replaced_seq(old_v.subrange(0, k), x, y)
                && v@.subrange(k, v@.len()) == old_v.subrange(k, old_v.len()),
    {
        if *elem == x {
            *elem = y;
        }
    }

    // At loop end, k = len, so the whole vector matches the replacement spec.
    assert(v@ == replaced_seq(old_v, x, y));
}

} // verus!

